import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireForms Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireForms/aireforms-v11-8-0.md","filePath":"aireblock-releases/AireForms/aireforms-v11-8-0.md","lastUpdated":1791984229000}`),a={name:`aireblock-releases/AireForms/aireforms-v11-8-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireforms-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireforms-icon.png"> AireForms Release Notes</span> <a class="header-anchor" href="#aireforms-release-notes" aria-label="Permalink to “AireForms Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 11.8.0<br><strong>Release Date:</strong> 21 October 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>New Bot Protection with Cloudflare Turnstile (AFORMS-4093)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>&quot;Other&quot; Free-Text Values Now Returned by the Extract API (AFORMS-4239)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="new-bot-protection-with-cloudflare-turnstile-aforms-4093" tabindex="-1">New Bot Protection with Cloudflare Turnstile (AFORMS-4093) <a class="header-anchor" href="#new-bot-protection-with-cloudflare-turnstile-aforms-4093" aria-label="Permalink to “New Bot Protection with Cloudflare Turnstile (AFORMS-4093)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>AireForms now uses Cloudflare Turnstile instead of Google reCAPTCHA to protect forms from automated submissions. This is the first phase of the change. During the switchover, forms that were opened before the release and still carry a reCAPTCHA token can still be submitted.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Your forms stay protected from spam and automated submissions. The people filling them in will see a new verification check in place of the familiar Google reCAPTCHA, and it usually completes on its own without them needing to do anything.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="other-free-text-values-now-returned-by-the-extract-api-aforms-4239" tabindex="-1">&quot;Other&quot; Free-Text Values Now Returned by the Extract API (AFORMS-4239) <a class="header-anchor" href="#other-free-text-values-now-returned-by-the-extract-api-aforms-4239" aria-label="Permalink to “&quot;Other&quot; Free-Text Values Now Returned by the Extract API (AFORMS-4239)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When &quot;Other&quot; is selected on a single-select control, the extract API now returns the text the user typed, as well as the &quot;Other&quot; option itself. Previously only the &quot;Other&quot; display name and its ID came back, and the typed value was missing. This brings single-select controls into line with how multi-select controls already behave.</p></div>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};